CREATE TABLE IF NOT EXISTS reservations (id BINARY(16) PRIMARY KEY, car_id BINARY(16) NOT NULL, renter_id BINARY(16) NOT NULL, start_time DATETIME(6) NOT NULL, end_time DATETIME(6) NOT NULL, status VARCHAR(15) NOT NULL, price_total DECIMAL(10, 2) NOT NULL, points_awarded INT DEFAULT 0 NOT NULL, CONSTRAINT fk_reservations_car_id__id FOREIGN KEY (car_id) REFERENCES cars(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_reservations_renter_id__id FOREIGN KEY (renter_id) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT);